package com.northstar.crm.ui;
import com.northstar.crm.domain.*;import com.northstar.crm.service.*;import com.vaadin.flow.component.button.Button;import com.vaadin.flow.component.combobox.ComboBox;import com.vaadin.flow.component.dialog.Dialog;import com.vaadin.flow.component.formlayout.FormLayout;import com.vaadin.flow.component.grid.Grid;import com.vaadin.flow.component.html.*;import com.vaadin.flow.component.orderedlayout.*;import com.vaadin.flow.component.textfield.*;import com.vaadin.flow.data.renderer.ComponentRenderer;import com.vaadin.flow.router.*;import jakarta.annotation.security.RolesAllowed;import static com.northstar.crm.domain.DomainTypes.*;
@Route(value="admin/users",layout=MainLayout.class)@PageTitle("People & access · Northstar")@RolesAllowed("PLATFORM_ADMIN")public class AdminUsersView extends VerticalLayout {
 private final AccountService accounts;private final PlanService plans;private final Grid<UserAccount> usersGrid=new Grid<>();private final Grid<PlanDefinition> planGrid=new Grid<>();
 public AdminUsersView(AccountService accounts,PlanService plans){this.accounts=accounts;this.plans=plans;configureUsers();configurePlans();var userPanel=new VerticalLayout(new H2("User management"),new Paragraph("Role changes and account access are applied without impersonation and written to the immutable audit ledger."),usersGrid);userPanel.addClassName("panel");var planPanel=new VerticalLayout(new H2("Plan reference settings"),new Paragraph("Prices and operational limits are server-owned fixed-precision reference values."),planGrid);planPanel.addClassName("panel");add(UiKit.page("PLATFORM ADMINISTRATION","People & access","Manage identities, role boundaries and server-owned plan policy.",userPanel,planPanel));setPadding(false);setSizeFull();refreshUsers();refreshPlans();}
 private void configureUsers(){usersGrid.addColumn(UserAccount::getDisplayName).setHeader("Person");usersGrid.addColumn(UserAccount::getEmail).setHeader("Email").setFlexGrow(2);usersGrid.addColumn(new ComponentRenderer<>(u->UiKit.badge(u.getRole()))).setHeader("Role");usersGrid.addColumn(u->u.isEnabled()?"Enabled":"Disabled").setHeader("Account");usersGrid.addComponentColumn(u->{var role=new ComboBox<Role>();role.setItems(Role.values());role.setValue(u.getRole());role.setAriaLabel("Role for "+u.getDisplayName());role.addValueChangeListener(e->{if(e.isFromClient())try{accounts.changeRole(u.getId(),e.getValue());refreshUsers();UiKit.success("Role updated");}catch(Exception ex){role.setValue(u.getRole());UiKit.error(ex);}});return role;}).setHeader("Change role");usersGrid.addComponentColumn(u->new Button(u.isEnabled()?"Disable":"Enable",e->{try{accounts.setEnabled(u.getId(),!u.isEnabled());refreshUsers();UiKit.success("Account access updated");}catch(Exception ex){UiKit.error(ex);}})).setHeader("Access");usersGrid.addComponentColumn(u->new Button("Desk passphrase",e->{var field=new com.vaadin.flow.component.textfield.PasswordField("Desk passphrase");field.setWidthFull();var d=new Dialog();d.setHeaderTitle("Set desk passphrase for "+u.getDisplayName());d.add(field);d.getFooter().add(new Button("Cancel",x->d.close()),UiKit.primary("Save",x->{try{accounts.enrolDeskPassphrase(u.getId(),field.getValue());d.close();UiKit.success("Desk passphrase updated");}catch(Exception ex){UiKit.error(ex);}}));d.open();})).setHeader("Desk access");}
 private void configurePlans(){planGrid.addColumn(PlanDefinition::getName).setHeader("Plan");planGrid.addColumn(p->p.getCurrency()+" "+p.getMonthlyPrice()).setHeader("Monthly price");planGrid.addColumn(PlanDefinition::getUserLimit).setHeader("Users");planGrid.addColumn(PlanDefinition::getApiRateLimit).setHeader("API requests / min");planGrid.addComponentColumn(p->new Button("Edit policy",e->editPlan(p))).setHeader("Action");planGrid.setAllRowsVisible(true);}
 private void editPlan(PlanDefinition plan){var price=new BigDecimalField("Monthly price ("+plan.getCurrency()+")");price.setValue(plan.getMonthlyPrice());var users=new IntegerField("User limit");users.setMin(1);users.setValue(plan.getUserLimit());var rate=new IntegerField("API requests / minute");rate.setMin(1);rate.setValue(plan.getApiRateLimit());var dialog=new Dialog();dialog.setHeaderTitle("Edit "+plan.getName()+" policy");dialog.add(new FormLayout(price,users,rate));dialog.getFooter().add(new Button("Cancel",e->dialog.close()),UiKit.primary("Save policy",e->{try{plans.update(plan.getId(),price.getValue(),rate.getValue(),users.getValue());dialog.close();refreshPlans();UiKit.success("Plan policy updated");}catch(Exception ex){UiKit.error(ex);}}));dialog.open();}
 private void refreshUsers(){usersGrid.setItems(accounts.allUsers());}private void refreshPlans(){planGrid.setItems(plans.all());}
}
